mapper.select:
SELECT * FROM todo_tasks

  user_id = #{userId}


      AND deleted_at IS NULL
      AND (
        (completed_at IS NOT NULL AND completed_at >= #{dayStart} AND completed_at < #{dayEnd})
        OR (
          completed_at IS NULL AND (
            due_date = #{todayDate}
            OR (due_at IS NOT NULL AND due_at >= #{dayStart} AND due_at < #{dayEnd})
            OR (due_date IS NOT NULL AND due_date < #{todayDate})
            OR (due_at IS NOT NULL AND due_at < #{dayStart})
          )
        )
      )


      AND deleted_at IS NULL AND completed_at IS NULL
      AND (
        (due_date IS NOT NULL AND due_date > #{todayDate} AND due_date <= #{windowEndDate})
        OR (due_at IS NOT NULL AND due_at >= #{tomorrowStart} AND due_at < #{windowEndStart})
      )


      AND deleted_at IS NULL AND completed_at IS NOT NULL AND completed_at >= #{completedCutoff}


      AND deleted_at IS NOT NULL AND deleted_at >= #{trashCutoff}


      AND deleted_at IS NULL AND completed_at IS NULL



  AND deleted_at IS NULL AND completed_at IS NULL
  AND deleted_at IS NULL AND completed_at IS NOT NULL
  AND deleted_at IS NOT NULL
  AND list_id = #{listId}

    AND (title LIKE CONCAT('%', #{q}, '%') OR notes LIKE CONCAT('%', #{q}, '%'))


    AND (
      (due_date IS NOT NULL
        AND due_date >= #{dueFrom}
        AND due_date <= #{dueTo}
      )
      OR
      (due_at IS NOT NULL
        AND DATE(due_at) >= #{dueFrom}
        AND DATE(due_at) <= #{dueTo}
      )
    )




        AND (sort_rank > #{cursorKey} OR (sort_rank = #{cursorKey} AND id > #{cursorId}))


        AND (completed_at < #{cursorKey} OR (completed_at = #{cursorKey} AND id < #{cursorId}))


        AND (deleted_at < #{cursorKey} OR (deleted_at = #{cursorKey} AND id < #{cursorId}))


        AND (updated_at < #{cursorKey} OR (updated_at = #{cursorKey} AND id < #{cursorId}))





  ORDER BY completed_at DESC, id DESC
  ORDER BY deleted_at DESC, id DESC
  ORDER BY updated_at DESC, id DESC
  ORDER BY sort_rank ASC, id ASC

LIMIT #{limit}

SELECT t.* FROM todo_tasks t
INNER JOIN todo_task_tags tt ON tt.task_id = t.id AND tt.user_id = t.user_id
WHERE t.user_id = #{userId} AND tt.tag_id = #{tagId}

SELECT task_id, tag_id FROM todo_task_tags
WHERE user_id = #{userId} AND task_id IN
#{taskId}

SELECT * FROM todo_task_completions
WHERE user_id = #{userId} AND task_id = #{taskId}
ORDER BY completed_at DESC LIMIT 1
